INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('timberline-lodge', 'Timberline Lodge', 'Oregon', '🏔️', 'USA', 'Horror', '🔪', '1980s', ARRAY['The Shining']::text[], 'The real Overlook Hotel exteriors from Kubrick''s The Shining — no Room 237, we promise.', 'Built in the 1930s as a public works project on Oregon''s Mount Hood, Timberline Lodge is a showcase of handcrafted timber and stonework. Its exterior is the one Stanley Kubrick used for the snowbound Overlook in The Shining.', 'https://www.booking.com/hotel/us/timberline-lodge.html', 'https://upload.wikimedia.org/wikipedia/commons/0/0a/2017-07-15_Timberline_01.jpg', 'Kingofthedead (Wikimedia Commons, CC BY-SA 4.0)', 'linear-gradient(135deg,#3d5a5c,#1f3335)')
