INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('fairmont-banff-springs', 'Fairmont Banff Springs', 'Banff', '🏔️', 'Canada', 'Drama', '🎭', '1950s', ARRAY['River of No Return']::text[], 'Marilyn Monroe and Joe DiMaggio stayed at this Scottish Baronial-style castle hotel in 1953 while she filmed this Western adventure in the surrounding Rockies.', 'Opened in 1888 in Banff National Park, the Banff Springs hotel looks like a Scottish castle set among the Rockies. Its surroundings give River of No Return the sweeping mountain scenery of the Canadian Rockies.', 'https://www.booking.com/hotel/ca/fairmont-banff-srpings.html', 'https://upload.wikimedia.org/wikipedia/commons/2/2f/Banff_Springs_Hotel1.jpg', 'Diderot~commonswiki (Wikimedia Commons, CC BY-SA 3.0)', 'linear-gradient(135deg,#5c7a63,#2f4a38)')
