INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('copacabana-palace-rio', 'Copacabana Palace, A Belmond Hotel', 'Rio de Janeiro', '🏖️', 'Brazil', 'Action', '🎯', '1930s', ARRAY['Flying Down to Rio']::text[], 'The 1933 musical Flying Down to Rio put the hotel on the map, reimagining it as the Atlantic Hotel, with chorus girls dancing on airplane wings above Copacabana.', 'Opened in August 1923 on Copacabana Beach and built by the Guinle family, the Copacabana Palace is Rio''s most famous hotel. Its white façade and pool have welcomed film stars for a century.', 'https://www.booking.com/hotel/br/copacabana-palace.html', 'https://upload.wikimedia.org/wikipedia/commons/7/7a/Copacabana_Palace_-_Rio_de_Janeiro_-_20240709110621.jpg', 'Joalpe (Wikimedia Commons, CC BY-SA 4.0)', 'linear-gradient(135deg,#e8d8b8,#a8885a)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('ciragan-palace-kempinski-istanbul', 'Çırağan Palace Kempinski Istanbul', 'Istanbul', '🕌', 'Turkey', 'Action', '🕶️', '2010s', ARRAY['Skyfall']::text[], 'The Skyfall cast and crew held their Istanbul press photo call at this former Ottoman palace on the Bosphorus in April 2012, when Daniel Craig''s Bond returned to Turkey.', 'Completed in 1871 under Sultan Abdülaziz as an Ottoman imperial palace on the Bosphorus, the Çırağan was gutted by fire in 1910. It was restored in the 1980s and reopened as a luxury hotel.', 'https://www.booking.com/hotel/tr/ciragan-palace-kempinski-istanbul.html', 'https://upload.wikimedia.org/wikipedia/commons/7/74/Ciragan_Palace_2014.JPG', 'Moroder (Wikimedia Commons, CC BY-SA 3.0)', 'linear-gradient(135deg,#5a7a8a,#2e4a56)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('gstaad-palace', 'Gstaad Palace', 'Gstaad', '🏔️', 'Switzerland', 'Comedy', '😂', '1970s', ARRAY['The Return of the Pink Panther', 'The Palace']::text[], 'Exterior shots of the Swiss chalet-style hotel appear in Peter Sellers'' 1975 The Return of the Pink Panther, and Roman Polanski shot his 2023 film The Palace here.', 'Opened in 1913, the Gstaad Palace is a castle-like hotel above the Swiss resort of Gstaad that has hosted film stars and royals. Its chalet-castle silhouette is what you see in the Pink Panther films.', 'https://www.booking.com/hotel/ch/gstaad-palace.html', 'https://upload.wikimedia.org/wikipedia/commons/9/92/The_Gstaad_Palace.jpg', 'Samuel Barlow (Wikimedia Commons, CC BY-SA 4.0)', 'linear-gradient(135deg,#6f8fa8,#34506a)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('old-cataract-aswan', 'Sofitel Legend Old Cataract Aswan', 'Aswan', '🏜️', 'Egypt', 'Thriller', '🔪', '1970s', ARRAY['Death on the Nile']::text[], 'The 1978 Agatha Christie adaptation was shot at this Nile-side hotel, which also inspired the novel''s setting; Poirot''s Aswan scenes play out on its terraces.', 'Opened in 1899 on a rocky bluff above the Nile, the Old Cataract is among Egypt''s most storied hotels. Agatha Christie wrote part of Death on the Nile here, and the 1978 film shot on its terraces.', 'https://www.booking.com/hotel/eg/sohitel-legend-old-cataract.html', 'https://upload.wikimedia.org/wikipedia/commons/7/7a/Old_Cataract_Hotel_Aswan_%D9%81%D9%86%D8%AF%D9%82_%D9%83%D8%AA%D8%B1%D8%A7%D9%83%D8%AA.jpg', 'Ahmed Emad H (Wikimedia Commons, CC BY-SA 4.0)', 'linear-gradient(135deg,#d9a35f,#8a5a2b)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('carlton-cannes', 'Carlton Cannes, a Regent Hotel', 'Cannes', '🎞️', 'France', 'Romance', '💕', '1950s', ARRAY['To Catch a Thief', 'French Kiss']::text[], 'Hitchcock used the Carlton and its Croisette setting for Cary Grant and Grace Kelly''s Riviera romance in 1955, and large parts of the 1995 romcom French Kiss were filmed in and around the hotel.', 'Built in the early 1910s on the Croisette in Cannes, the Carlton is a Belle Époque landmark with twin domes. Its seafront setting made it a natural for the Riviera glamour of To Catch a Thief and French Kiss.', 'https://www.booking.com/hotel/fr/intercontinental-carlton-cannes.html', 'https://upload.wikimedia.org/wikipedia/commons/1/1b/Cannes_-_hotel_CARLTON.jpg', 'Christophe.Finot (Wikimedia Commons, CC BY-SA 2.5)', 'linear-gradient(135deg,#4a90b8,#1f4e6e)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('westin-grand-berlin', 'The Westin Grand Berlin', 'Berlin', '🐻', 'Germany', 'Action', '💥', '2000s', ARRAY['The Bourne Supremacy']::text[], 'Jason Bourne walks through the hotel''s grand foyer and up its sweeping staircase to reach CIA official Pamela Landy''s suite.', 'Opened in 1987 on Friedrichstrasse in central Berlin, the Westin Grand is known for its sweeping lobby staircase. That staircase is exactly what Jason Bourne climbs in The Bourne Supremacy.', 'https://www.booking.com/hotel/de/westingrand.html', 'https://upload.wikimedia.org/wikipedia/commons/0/0c/Berlin,_Mitte,_Friedrichstrasse_157-164,_Westin_Grand.jpg', 'Jörg Zägel (Wikimedia Commons, CC BY-SA 3.0)', 'linear-gradient(135deg,#5b6575,#2a303a)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('st-pancras-renaissance-london', 'St Pancras Renaissance Hotel London', 'London', '🎡', 'United Kingdom', 'Action', '🦇', '2000s', ARRAY['Batman Begins', 'The Secret Garden']::text[], 'The Gothic Revival former Midland Grand Hotel doubled for Arkham Asylum''s stairwell in Batman Begins (2005), and its grand staircase also served as Mistlethwaite Manor in The Secret Garden (1993).', 'Opened as the Midland Grand Hotel in 1873 and restored as a hotel in 2011, this Gothic Revival masterpiece fronts St Pancras station. Its grand staircase and red-brick spires have given films a ready-made Gothic setting.', 'https://www.booking.com/hotel/gb/renaissance-st-pancras-london.en-gb.html', 'https://upload.wikimedia.org/wikipedia/commons/3/30/St_Pancras_Renaissance_London_Hotel_2011-06-19.jpg', 'LepoRello (Wikimedia Commons, CC BY-SA 3.0)', 'linear-gradient(135deg,#9a4a3a,#55241c)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('marina-bay-sands-singapore', 'Marina Bay Sands', 'Singapore', '🦁', 'Singapore', 'Romance', '💕', '2010s', ARRAY['Crazy Rich Asians']::text[], 'The 57th-floor SkyPark and its record-size rooftop infinity pool star in Crazy Rich Asians (2018), setting the stage for the film''s glittering engagement party.', 'Opened in 2010 and designed by Moshe Safdie, Marina Bay Sands is three towers topped by a ship-shaped SkyPark. Its rooftop infinity pool is the signature image of Crazy Rich Asians.', 'https://www.booking.com/hotel/sg/marina-bay-sands.html', 'https://upload.wikimedia.org/wikipedia/commons/a/a3/Marina_Bay_Sands_Singapore_by_day.jpg', 'Medtd1 (Wikimedia Commons, CC BY-SA 4.0)', 'linear-gradient(135deg,#2a9d8f,#1b4d5c)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('beverly-hills-hotel', 'The Beverly Hills Hotel', 'Beverly Hills', '🌴', 'United States', 'Comedy', '😂', '1980s', ARRAY['Troop Beverly Hills']::text[], 'The ''Pink Palace'' on Sunset Boulevard is the glamorous backdrop for Troop Beverly Hills (1989), where the Wilderness Girls troop camps in a hotel bungalow.', 'Opened in 1912 and known as the Pink Palace, the Beverly Hills Hotel has long been a hangout for the entertainment business. Its pink exterior, palm-lined drive and bungalows are the setting of Troop Beverly Hills.', 'https://www.booking.com/hotel/us/the-beverly-hills.html', 'https://upload.wikimedia.org/wikipedia/commons/4/47/The_Beverly_Hills_Hotel_(2013).jpg', 'Alan Light (Wikimedia Commons, CC BY 2.0)', 'linear-gradient(135deg,#f4a6b8,#b8567a)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('hotel-de-paris-monte-carlo', 'Hôtel de Paris Monte-Carlo', 'Monte Carlo', '🎰', 'Monaco', 'Action', '🦇', '1990s', ARRAY['GoldenEye', 'Never Say Never Again']::text[], 'Standing beside the Casino de Monte-Carlo, this Belle Époque hotel appears in the James Bond films Never Say Never Again (1983) and GoldenEye (1995).', 'Opened in 1864 beside the Casino de Monte-Carlo, the Hôtel de Paris is the symbol of Monaco''s Belle Époque glamour. Its location on the casino square made it a natural fit for James Bond''s Riviera scenes.', 'https://www.booking.com/hotel/mc/ha-tel-de-paris.html', 'https://upload.wikimedia.org/wikipedia/commons/d/d5/2016_Hotel_de_Paris_-_Monaco_01.jpg', 'Jordiferrer (Wikimedia Commons, CC BY-SA 4.0)', 'linear-gradient(135deg,#c9a24b,#6b4f17)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('raffles-singapore', 'Raffles Singapore', 'Singapore', '🦁', 'Singapore', 'Romance', '💕', '2010s', ARRAY['Crazy Rich Asians']::text[], 'The colonial-era landmark plays the fictional Kingsford Hotel in Crazy Rich Asians (2018), where Nick and Rachel stay when she isn''t welcome at his family''s home.', 'Opened in 1887 and named after Sir Stamford Raffles, the hotel was gazetted a national monument in 1987. Its Long Bar is where the Singapore Sling cocktail is said to have been invented.', 'https://www.booking.com/hotel/sg/raffles.html', 'https://upload.wikimedia.org/wikipedia/commons/6/63/Front_facade_of_Raffles_Hotel,_Singapore,_from_southeast.jpg', 'Daniel Case (Wikimedia Commons, CC BY-SA 4.0)', 'linear-gradient(135deg,#d9c9a3,#8a7a52)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('plaza-athenee-paris', 'Hôtel Plaza Athénée', 'Paris', '🗼', 'France', 'Romance', '💕', '2000s', ARRAY['Sex and the City', 'Something''s Gotta Give', 'Emily in Paris']::text[], 'Carrie Bradshaw stays at the Plaza Athénée in the Paris finale of Sex and the City, with its Eiffel Tower balcony view; the hotel also appears in Something''s Gotta Give and Emily in Paris.', 'Opened in April 1913 on Avenue Montaigne, the Plaza Athénée has a classically French main building topped by Art Deco upper floors. Its red window awnings and geranium-filled window boxes make it easy to spot.', 'https://www.booking.com/hotel/fr/ha-tel-plaza-atha-c-na-c-e-paris.html', 'https://upload.wikimedia.org/wikipedia/commons/5/58/Facade_of_the_H%C3%B4tel_Plaza_Ath%C3%A9n%C3%A9e,_Paris_17_July_2017.jpg', 'Joe deSousa (Wikimedia Commons, CC0)', 'linear-gradient(135deg,#c9585f,#7a2e3b)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('jumeirah-zabeel-saray-dubai', 'Jumeirah Zabeel Saray', 'Dubai', '🏙️', 'United Arab Emirates', 'Action', '💥', '2010s', ARRAY['Mission: Impossible – Ghost Protocol']::text[], 'The Ottoman-style lobby doubled as a Mumbai palace for the black-tie party scene in Mission: Impossible – Ghost Protocol (2011), shot over several days with hundreds of extras before the hotel opened.', 'Opened in 2011 on the West Crescent of Palm Jumeirah, the resort is modelled on the palaces of the Ottoman Empire. Hand-painted finishes, Turkish artworks and murals fill its interiors.', 'https://www.booking.com/hotel/ae/jumeirah-zabeel-saray.html', 'https://upload.wikimedia.org/wikipedia/commons/0/03/Jumeirah_Zabeel_Saray_-_panoramio.jpg', 'Сергей Секачёв (Wikimedia Commons, CC BY-SA 3.0)', 'linear-gradient(135deg,#d4a35a,#7a4a2a)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('hotel-sacher-vienna', 'Hotel Sacher Wien', 'Vienna', '🎻', 'Austria', 'Drama', '🎭', '2010s', ARRAY['Das Sacher', 'Hotel Sacher']::text[], 'The Austrian TV drama Das Sacher (2016) tells the story of the hotel around 1900 and was partly shot at the real Hotel Sacher; the 1939 German film Hotel Sacher made the name famous earlier.', 'Opened in 1876 by Eduard Sacher opposite the Vienna State Opera, on the site of the old Theater am Kärntnertor. The neo-Renaissance building is home to the original Sachertorte.', 'https://www.booking.com/hotel/at/sacher-wien.html', 'https://upload.wikimedia.org/wikipedia/commons/a/a6/Wien_Hotel_Sacher.jpg', 'Andrzej Otrębski (Wikimedia Commons, CC BY-SA 4.0)', 'linear-gradient(135deg,#b5483f,#5e1f1f)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('burgh-island-hotel', 'Burgh Island Hotel', 'Bigbury-on-Sea, Devon', '🏝️', 'United Kingdom', 'Thriller', '🔍', '2000s', ARRAY['Evil Under the Sun', 'Nemesis', 'Catch Us If You Can']::text[], 'The Art Deco island hotel stood in for the setting of Agatha Christie''s Evil Under the Sun in the 2001 Poirot TV adaptation, and was used in the 1987 Miss Marple story Nemesis and the climax of the 1965 film Catch Us If You Can.', 'Opened in 1929 on a tidal island off the Devon coast, designed by Matthew Dawson for Archibald Nettlefold. The Grade II listed Art Deco building has 25 rooms, and a guest room was built from the captain''s cabin of HMS Ganges (1821).', 'https://www.booking.com/hotel/gb/burgh-island.html', 'https://upload.wikimedia.org/wikipedia/commons/6/69/Burgh_Island_Hotel.jpg', 'Jason Ballard (Wikimedia Commons, CC BY 2.0)', 'linear-gradient(135deg,#4a8fa8,#1f4a5e)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('rosewood-schloss-fuschl', 'Rosewood Schloss Fuschl', 'Fuschl am See, Salzburg', '🏰', 'Austria', 'Romance', '💕', '1950s', ARRAY['Sissi']::text[], 'The lakeside castle was the setting for the first Sissi film (1955), standing in for Schloss Possenhofen; Romy Schneider stayed at the castle during filming and a suite is dedicated to her today.', 'Built in 1461 as a hunting lodge for the Prince-Archbishops of Salzburg on a peninsula in Lake Fuschl. It was converted into a castle hotel in 1950 and today also houses a Sissi museum.', 'https://www.booking.com/hotel/at/rosewood-schloss-fuschl.html', 'https://upload.wikimedia.org/wikipedia/commons/5/56/Fuschlschloss02.jpg', 'waterborough (Wikimedia Commons, Public Domain)', 'linear-gradient(135deg,#8e7cc3,#5b4a8a)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('lebua-state-tower-bangkok', 'lebua at State Tower', 'Bangkok', '🌆', 'Thailand', 'Comedy', '😂', '2010s', ARRAY['The Hangover Part II']::text[], 'The Wolf Pack meets Paul Giamatti''s character at one of the tower''s restaurants and later returns to the Sky Bar high above Bangkok; the hotel now offers a "Hangover" suite and a Hangovertini cocktail.', 'The 247-metre State Tower on the Chao Phraya River in Bang Rak opened in 2006. Its upper floors hold the Dome by lebua, a cluster of rooftop restaurants and bars including Sirocco and the Sky Bar.', 'https://www.booking.com/hotel/th/lebua-at-state-tower.html', 'https://upload.wikimedia.org/wikipedia/commons/7/7d/State_Tower,_BKK_(I).jpg', 'Supanut Arunoprayote (Wikimedia Commons, CC BY 4.0)', 'linear-gradient(135deg,#d4a017,#7a4a0e)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('hotel-gellert-budapest', 'Danubius Hotel Gellért', 'Budapest', '🏛️', 'Hungary', 'Thriller', '🔪', '2010s', ARRAY['Red Sparrow', 'I Spy', 'Mephisto']::text[], 'In Red Sparrow (2018) the Art Nouveau building stood in for a CIA base in Russia; it also appeared in the comedy I Spy (2002) and the Oscar-winning drama Mephisto (1981).', 'Opened on 26 September 1918 beside the Danube at the foot of Gellért Hill, designed by Ármin Hegedűs, Artúr Sebestyén and Izidor Sterk. The Secessionist exterior and Art Nouveau interiors are linked to the famous Gellért thermal baths.', 'https://www.booking.com/hotel/hu/gellert.html', 'https://upload.wikimedia.org/wikipedia/commons/4/41/HotelGellert.JPG', 'WikiTamasB (Wikimedia Commons, CC BY-SA 3.0)', 'linear-gradient(135deg,#4a8fa8,#1f4a5e)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('miami-biltmore-coral-gables', 'Biltmore Hotel Miami Coral Gables', 'Miami (Coral Gables)', '🌴', 'United States', 'Action', '💥', '1990s', ARRAY['Bad Boys', 'Miami Vice']::text[], 'The Spanish Revival landmark appears in the Will Smith and Martin Lawrence action hit Bad Boys (1995) and was a recurring location for the TV series Miami Vice.', 'Opened in January 1926 and designed by Schultze and Weaver in a Mission/Spanish Revival style, with a tower inspired by the Giralda in Seville. At 315 feet it was Florida''s tallest building until 1928.', 'https://www.booking.com/hotel/us/biltmore.html', 'https://upload.wikimedia.org/wikipedia/commons/1/14/Coral_Gables_FL_Biltmore02.jpg', 'Ebyabe (Wikimedia Commons, CC BY-SA 3.0)', 'linear-gradient(135deg,#e07a5f,#8a3a24)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('palacio-estoril', 'Palácio Estoril Hotel, Golf & Wellness', 'Estoril (Cascais)', '🌊', 'Portugal', 'Action', '💥', '1960s', ARRAY['On Her Majesty''s Secret Service']::text[], 'James Bond checks into this seaside grand hotel in On Her Majesty''s Secret Service (1969); its exterior, lobby, pool and rooms were all filmed here, and the cast and crew stayed on site.', 'Opened in 1930 and founded by Fausto Figueiredo, the hotel was designed by architect Henry Martinet as a spa, sports and leisure destination on the Portuguese Riviera. It sits opposite the Estoril Casino and gardens and has hosted royalty in exile and spies alike.', 'https://www.booking.com/hotel/pt/palacio-estoril-golf.html', 'https://upload.wikimedia.org/wikipedia/commons/0/03/Front_of_the_Hotel_Palacio_in_Estoril.JPG', 'Carcharoth (Wikimedia Commons, CC BY-SA 3.0)', 'linear-gradient(135deg,#4aa3b8,#1d5568)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('gran-hotel-ciudad-de-mexico', 'Gran Hotel Ciudad de México', 'Mexico City', '🌮', 'Mexico', 'Action', '💥', '2010s', ARRAY['Spectre']::text[], 'Bond and Estrella ride the hotel''s cage-style elevator in the opening sequence of Spectre (2015); the interior scenes were filmed inside the real hotel, although the street entrance was shot at another building.', 'The building dates to 1899, when it opened as El Centro Mercantil, one of Latin America''s most luxurious department stores. It became a hotel in the late 1960s and is known for its Tiffany-style stained-glass ceiling and two of the oldest working elevators in Latin America.', 'https://www.booking.com/hotel/mx/gran-ciudad-de-mexico.html', 'https://upload.wikimedia.org/wikipedia/commons/a/ab/FacadeHotelCiudadMexicoDF.JPG', 'Thelmadatter (Wikimedia Commons, CC BY-SA 3.0)', 'linear-gradient(135deg,#d99a3d,#7a4a14)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('hotel-maria-cristina-san-sebastian', 'Hotel María Cristina, a Luxury Collection Hotel', 'San Sebastián', '🏖️', 'Spain', 'Comedy', '😂', '2020s', ARRAY['Rifkin''s Festival']::text[], 'In Woody Allen''s Rifkin''s Festival (2020), the hotel is where the characters attending the San Sebastián film festival stay; Allen''s own family also moved in during the shoot.', 'Opened on 9 July 1912, the Belle Époque hotel was planned by French architect Charles Mewès, known for his work on Ritz hotels. It stands on Plaza Okendo beside the Urumea River, opposite the Victoria Eugenia Theatre, and reopened in 1987 after a full restoration.', 'https://www.booking.com/hotel/es/maria-cristina-san-sebastian.html', 'https://upload.wikimedia.org/wikipedia/commons/0/0e/San_Sebastian_-_Hotel_Maria_Cristina_1.JPG', 'Zarateman (Wikimedia Commons, CC0)', 'linear-gradient(135deg,#8e7cc3,#5b4a8a)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('sunset-tower-hotel-los-angeles', 'Sunset Tower Hotel', 'West Hollywood', '🌴', 'United States', 'Crime', '🕵️', '1990s', ARRAY['The Player', 'Get Shorty']::text[], 'Robert Altman''s The Player (1992) features a pivotal scene shot by the hotel pool, and the Art Deco tower also appears in Get Shorty (1995).', 'Designed by Leland A. Bryant and completed in 1931, the Streamline Moderne tower first opened as a luxury apartment hotel on Sunset Boulevard. At 15 stories, it is considered one of the finest Art Deco buildings in the Los Angeles area and is listed on the National Register of Historic Places.', 'https://www.booking.com/hotel/us/sunset-tower.html', 'https://upload.wikimedia.org/wikipedia/commons/2/22/Sunset_Tower,_8358_Sunset_Blvd._West_Hollywood_2364.jpg', 'MikeJiroch (Wikimedia Commons, CC BY-SA 3.0)', 'linear-gradient(135deg,#d4a373,#8c5a3c)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('hotel-raphael-paris', 'Hôtel Raphael', 'Paris', '🗼', 'France', 'Drama', '🎞️', '2000s', ARRAY['Hotel Chevalier', 'Place Vendôme']::text[], 'Wes Anderson''s short Hotel Chevalier (2007), the prologue to The Darjeeling Limited, plays out in a Paris hotel room where Jason Schwartzman''s Jack is surprised by Natalie Portman''s Rhett. The hotel also appears in Place Vendôme (1998).', 'Opened in 1925 on Avenue Kléber, a short walk from the Arc de Triomphe, the Raphael is an Art Deco hotel named as a tribute to the painter Raphael. Some of its rooms look out toward the Eiffel Tower or the Arc de Triomphe.', 'https://www.booking.com/hotel/fr/raphael.html', 'https://upload.wikimedia.org/wikipedia/commons/a/a0/H%C3%B4tel_Rapha%C3%ABl%2C_Paris_2.jpg', 'Peter Potrowl (Wikimedia Commons, CC BY-SA 3.0)', 'linear-gradient(135deg,#b08968,#6f4e37)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('hotel-regina-louvre-paris', 'Hôtel Regina Louvre', 'Paris', '🗼', 'France', 'Thriller', '🔪', '2000s', ARRAY['The Bourne Identity', 'La Femme Nikita']::text[], 'In The Bourne Identity (2002), the hotel lobby is where Marie carries out a plan she has agreed with Bourne. The hotel is also listed among the filming locations of La Femme Nikita (1990).', 'Built in 1898-1900 for the Paris World''s Fair, the Régina is a Second Empire building on Place des Pyramides, across Rue de Rivoli from the Tuileries Garden and an entrance to the Louvre. A gilded statue of Joan of Arc on horseback stands in the square in front of it.', 'https://www.booking.com/hotel/fr/regina-paris.html', 'https://upload.wikimedia.org/wikipedia/commons/c/c8/H%C3%B4tel_R%C3%A9gina%2C_Place_des_Pyramides%2C_Paris_30_July_2015.jpg', 'ndiggity from USA (Wikimedia Commons, CC BY-SA 2.0)', 'linear-gradient(135deg,#7a8ba3,#3d4a5c)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('king-david-jerusalem', 'King David Hotel Jerusalem', 'Jerusalem', '🕍', 'Israel', 'Drama', '🎭', '1960s', ARRAY['Exodus']::text[], 'Otto Preminger''s 1960 epic Exodus shot several scenes at the hotel, outside and in the main lobby, including a scene on its terrace with Paul Newman.', 'Opened in 1931 and built from locally quarried pink limestone, the King David was founded by the Egyptian Jewish banker Ezra Mosseri. It stands on King David Street, overlooking the Old City and Mount Zion, and has long hosted visiting heads of state and celebrities.', 'https://www.booking.com/hotel/il/king-david-jerusalem.html', 'https://upload.wikimedia.org/wikipedia/commons/b/b9/Jerusalem_-_King_David_Hotel_P1140870.JPG', 'Deror_avi (Wikimedia Commons, CC BY-SA 3.0)', 'linear-gradient(135deg,#d9a574,#8c5a3c)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('mount-lavinia-hotel-colombo', 'Mount Lavinia Hotel', 'Colombo', '🌴', 'Sri Lanka', 'Drama', '🎭', '1950s', ARRAY['The Bridge on the River Kwai']::text[], 'In 1957 David Lean''s The Bridge on the River Kwai filmed a number of scenes here, and the building stands in for the military hospital in the film.', 'The building began as a residence for Sir Thomas Maitland, the second governor of British Ceylon, who ordered it built in 1806 on the coast at Mount Lavinia. It has operated continuously as a hotel since 1947 and today has 275 rooms on the beachfront.', 'https://www.booking.com/hotel/lk/mount-lavinia.html', 'https://upload.wikimedia.org/wikipedia/commons/b/bb/Mount_Lavinia_Hotel_Sri_Lanka_(30039549556).jpg', 'dronepicr (Wikimedia Commons, CC BY 2.0)', 'linear-gradient(135deg,#5aa3b8,#2d5d73)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('waldorf-astoria-new-york', 'Waldorf Astoria New York', 'New York', '🗽', 'United States', 'Drama', '🎭', '1990s', ARRAY['Week-End at the Waldorf', 'Scent of a Woman']::text[], 'The 1945 comedy-drama Week-End at the Waldorf is set at the hotel and was partly filmed on location there. In Scent of a Woman (1992), Al Pacino''s Frank Slade and Chris O''Donnell''s Charlie check in for their New York weekend at the Waldorf.', 'The current Art Deco tower on Park Avenue was designed by Schultze and Weaver and completed in 1931, and was the world''s tallest hotel until 1957. It replaced the original Waldorf-Astoria on Fifth Avenue, which was demolished in 1929 to make way for the Empire State Building. After closing in 2017, it reopened as a restored hotel with 375 rooms, with the upper floors turned into private residences.', 'https://www.booking.com/hotel/us/the-waldorf-astoria.html', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/aa/Waldorf_Astoria_New_York_%2855272623437%29.jpg/1280px-Waldorf_Astoria_New_York_%2855272623437%29.jpg', 'Ajay Suresh (Wikimedia Commons, CC BY 4.0)', 'linear-gradient(135deg,#c9a45c,#6b4f1d)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('the-savoy-london', 'The Savoy', 'London', '🎡', 'United Kingdom', 'Romance', '💕', '1990s', ARRAY['Notting Hill']::text[], 'The romantic finale of Notting Hill (1999) plays out at Anna Scott''s press conference in the hotel''s Lancaster Room, where William declares his feelings in front of the press.', 'The Savoy opened on the Strand on 6 August 1889, built by impresario Richard D''Oyly Carte with the profits of Gilbert and Sullivan. Designed by Thomas Edward Collcutt, it was the first hotel in Britain lit entirely by electric light and the first with electric lifts. Today it is a Grade II listed hotel managed by Fairmont.', 'https://www.booking.com/hotel/gb/the-savoy.html', 'https://upload.wikimedia.org/wikipedia/commons/c/c1/Entrance_to_the_Savoy_Hotel,_London_-_geograph.org.uk_-_2281522.jpg', 'Anthony O''Neil (Wikimedia Commons, CC BY-SA 2.0)', 'linear-gradient(135deg,#b8975a,#3d3425)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('hilton-london-hyde-park', 'Hilton London Hyde Park', 'London', '🎡', 'United Kingdom', 'Thriller', '🔪', '1970s', ARRAY['Frenzy']::text[], 'In Alfred Hitchcock''s Frenzy (1972), Richard Blaney and Babs Milligan check in here, then called the Coburg Hotel, as "Mr. and Mrs. Oscar Wilde". Filming took place at the hotel in 1971, with most interiors recreated at Pinewood Studios.', 'The hotel on Bayswater Road, overlooking Hyde Park, opened in 1907 as the Coburg Court Hotel. It became the Coburg Hotel in the early 1960s and has been the Hilton London Hyde Park since July 1999.', 'https://www.booking.com/hotel/gb/hilton-london-hyde-park.html', 'https://upload.wikimedia.org/wikipedia/commons/d/de/Hilton_London_Hyde_Park_Hotel,_Bayswater_Road,_London_W2_-_geograph.org.uk_-_1149723.jpg', 'Stacey Harris (Wikimedia Commons, CC BY-SA 2.0)', 'linear-gradient(135deg,#6b7a8f,#2c3440)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('esplanade-zagreb', 'The Esplanade Zagreb Hotel', 'Zagreb', '🏙️', 'Croatia', 'Action', '💥', '2020s', ARRAY['Canary Black', 'The Winds of War']::text[], 'The hotel was a filming location for the spy thriller Canary Black (2024), starring Kate Beckinsale, with both exterior and interior scenes shot here. It was also a filming site for the 1983 miniseries The Winds of War.', 'The Esplanade opened on 22 April 1925 to house passengers of the Orient Express. The winning design by Otto Rehnig was reworked by Dionis Sunko, and the Belle Epoque building underwent a major restoration before reopening in 2004. It has operated as an independent hotel since 2012.', 'https://www.booking.com/hotel/hr/esplanade-zagreb-hotel.html', 'https://upload.wikimedia.org/wikipedia/commons/7/78/Hotel_Esplanade,_Zagreb_1.jpg', 'Rangan Datta Wiki (Wikimedia Commons, CC BY-SA 4.0)', 'linear-gradient(135deg,#8e7cc3,#5b4a8a)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('fairmont-san-francisco', 'Fairmont San Francisco', 'San Francisco', '🌉', 'United States', 'Drama', '🎭', '1980s', ARRAY['Hotel']::text[], 'Establishing shots and some interiors for the 1980s ABC series Hotel were filmed at the Fairmont, which stood in for the fictional St. Gregory Hotel.', 'The Fairmont opened on 18 April 1907, a year after the 1906 earthquake and fire gutted the original building. Architect Julia Morgan oversaw the rebuild of the Beaux-Arts landmark, and the tower was added in 1962. It sits on Nob Hill and still houses the Tonga Room.', 'https://www.booking.com/hotel/us/the-fairmont-san-francisco-san-francisco-california.html', 'https://upload.wikimedia.org/wikipedia/commons/b/b8/San_Francisco_(CA,_USA),_Hotel_Fairmont_--_2022_--_2940.jpg', 'Dietmar Rabich (Wikimedia Commons, CC BY-SA 4.0)', 'linear-gradient(135deg,#8e7cc3,#5b4a8a)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

